      lede: 'कोडेड इनइक्वॉलिटी के प्रश्न आपको अक्षरों के बीच क्रम-संबंधों की एक श्रृंखला देते हैं और पूछते हैं कि कौन से निष्कर्ष निश्चित रूप से लागू होते हैं — तर्क सिलोजिज़्म जैसा ही है, बस सेट-सदस्यता के बजाय क्रम के साथ। यहां तरीका, चार पूरी तरह हल किए गए उदाहरण जो सबसे ज़्यादा उलझाने वाले पैटर्न को कवर करते हैं, और खुद हल करने के लिए कुछ प्रश्न दिए गए हैं।',
